# ContainerRecord: dataclass + validator
from dataclasses import dataclass, field
from typing import Any

@dataclass
class Containerrecord:
    container_id: str = None  # ID
    kind: str = None  # 20ft/40ft/reefer
    shipment_id: str = None  # FK
    seal: str = None  # Seal #
    status: str = None  # loaded/discharged/empty

REQUIRED = ["container_id", "kind", "shipment_id", "seal"]

def validate(rec: dict) -> list:
    errors = []
    for f in REQUIRED:
        if f not in rec or rec[f] is None:
            errors.append(f'missing: {f}')
    return errors

sample = {'container_id': 'TCLU 881201-0', 'kind': '40ft', 'shipment_id': 'SHP-991201', 'seal': 'S-44120', 'status': 'loaded'}
print('validation errors:', validate(sample))
print('record ok:', not validate(sample))

